<template>
 <div>
  <div class="page-heading"><div><p class="eyebrow">项目台账 · 计划协同</p><h1>项目台账与计划</h1><p>项目、工作包与任务共用人员档案；草稿完善后发布。</p></div><el-button type="primary" @click="open()">新建项目</el-button></div>
  <ProjectImport @draft="open"/><el-upload action="#" accept=".xml" :show-file-list="false" :http-request="importXml"><el-button>导入 Microsoft Project XML 草稿</el-button></el-upload><p>XML保留基础计划结构；PDF、邮件和合同可识别为待完善草稿。扫描PDF需启用MinerU连接器，MPP原生文件暂不支持。</p><div class="table-toolbar"><el-input v-model="keyword" clearable placeholder="项目编号或名称" @keyup.enter.native="page=1;load()"/><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="(label,key) in statuses" :key="key" :label="label" :value="key"/></el-select><el-button @click="page=1;load()">查询</el-button></div>
  <el-table :data="items" v-loading="loading"><el-table-column prop="code" label="编号"/><el-table-column prop="name" label="项目名称"/><el-table-column label="状态"><template slot-scope="s">{{statuses[s.row.status]}}</template></el-table-column><el-table-column label="项目经理"><template slot-scope="s">{{staffName(s.row.manager_id)}}</template></el-table-column><el-table-column prop="budget" label="预算"/><el-table-column prop="currency" label="币种"/><el-table-column label="操作" width="180"><template slot-scope="s"><el-button type="text" @click="open(s.row)">编辑 / 甘特图</el-button><el-button v-if="s.row.status==='draft'" type="text" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table>
  <el-pagination :current-page.sync="page" :page-size="10" :total="total" layout="total,prev,pager,next" @current-change="load"/>
  <el-dialog title="项目与计划" :visible.sync="visible" width="94%" :close-on-click-modal="false">
   <el-form label-width="90px" :disabled="saving"><el-row :gutter="16"><el-col :span="8"><el-form-item label="项目编号"><el-input v-model.trim="form.code"/></el-form-item></el-col><el-col :span="8"><el-form-item label="项目名称"><el-input v-model.trim="form.name"/></el-form-item></el-col><el-col :span="8"><el-form-item label="项目经理"><el-select v-model="form.manager_id" filterable clearable><el-option v-for="s in staff" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col></el-row>
   <el-row :gutter="16"><el-col :span="8"><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="(label,key) in statuses" :key="key" :label="label" :value="key"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="预算"><el-input-number v-model="form.budget" :min="0" :precision="2"/></el-form-item></el-col><el-col :span="8"><el-form-item label="币种"><el-input v-model="form.currency"/></el-form-item></el-col></el-row><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form>
   <el-collapse v-if="form.import_evidence"><el-collapse-item title="导入来源与待确认项"><p>{{form.import_evidence.filename}} · {{form.import_evidence.engine}}</p><p v-for="w in form.import_evidence.warnings" :key="w">{{w}}</p><pre style="white-space:pre-wrap;max-height:220px;overflow:auto">{{form.import_evidence.source_text}}</pre></el-collapse-item></el-collapse><el-tabs v-model="tab"><el-tab-pane label="工作包与任务" name="tasks"><el-button @click="addTask">增加任务</el-button><p>日期采用日历日；当前甘特图不自动排程。发布前所有任务须填写负责人及日期。</p>
    <el-table :data="form.tasks" max-height="450"><el-table-column label="任务名称" min-width="180"><template slot-scope="s"><el-input v-model="s.row.name"/></template></el-table-column><el-table-column label="类型" width="130"><template slot-scope="s"><el-select v-model="s.row.kind"><el-option label="工作包" value="work_package"/><el-option label="任务" value="task"/><el-option label="里程碑" value="milestone"/></el-select></template></el-table-column><el-table-column label="上级" width="140"><template slot-scope="s"><el-select v-model="s.row.parent_id" clearable><el-option v-for="t in form.tasks.filter(t=>t.id!==s.row.id)" :key="t.id" :label="t.name" :value="t.id"/></el-select></template></el-table-column><el-table-column label="负责人" width="140"><template slot-scope="s"><el-select v-model="s.row.owner_id" filterable clearable><el-option v-for="t in staff" :key="t.id" :label="t.name" :value="t.id"/></el-select></template></el-table-column><el-table-column label="开始" width="155"><template slot-scope="s"><el-date-picker v-model="s.row.start" value-format="yyyy-MM-dd" style="width:140px"/></template></el-table-column><el-table-column label="结束" width="155"><template slot-scope="s"><el-date-picker v-model="s.row.finish" value-format="yyyy-MM-dd" style="width:140px"/></template></el-table-column><el-table-column label="完成%" width="120"><template slot-scope="s"><el-input-number v-model="s.row.progress" :min="0" :max="100" controls-position="right" style="width:95px"/></template></el-table-column><el-table-column label="前置任务" width="160"><template slot-scope="s"><el-select v-model="s.row.predecessors" multiple><el-option v-for="t in form.tasks.filter(t=>t.id!==s.row.id)" :key="t.id" :label="t.name" :value="t.id"/></el-select></template></el-table-column><el-table-column label="操作" width="70"><template slot-scope="s"><el-button type="text" @click="deleteTask(s.row.id)">移除</el-button></template></el-table-column></el-table>
   </el-tab-pane><el-tab-pane label="项目甘特图" name="gantt"><ProjectGantt :tasks="form.tasks" :staff="staff" :disabled="saving||['completed','archived'].includes(form.status)" @shift="shiftSchedule"/></el-tab-pane><el-tab-pane label="节点提醒" name="alerts"><el-button :disabled="!form.id" @click="checkAlerts">检查已保存计划</el-button><p>当前为站内逾期检查，不会自动发送邮件。</p><el-table :data="alerts"><el-table-column prop="task" label="任务"/><el-table-column prop="type" label="提醒"/><el-table-column prop="due" label="截止日"/><el-table-column label="负责人"><template slot-scope="s">{{staffName(s.row.owner_id)}}</template></el-table-column></el-table></el-tab-pane><el-tab-pane label="计划基线" name="baseline"><el-button :disabled="!form.id" @click="loadBaselines">刷新基线与日期差异</el-button><el-button :disabled="!form.id||form.status!=='active'" @click="createBaseline">确认已保存计划为基线</el-button><p>基线保留服务端已保存计划；当前只比较任务新增、移除与日期变化，不自动调整计划。</p><el-collapse><el-collapse-item v-for="b in baselines" :key="b.id" :title="'v'+b.version+' · '+b.created_at+' · '+b.created_by"><el-table :data="b.changes"><el-table-column prop="name" label="任务"/><el-table-column prop="change" label="变化"/><el-table-column label="基线日期"><template slot-scope="s">{{s.row.before.join(' → ')}}</template></el-table-column><el-table-column label="当前日期"><template slot-scope="s">{{s.row.after.join(' → ')}}</template></el-table-column></el-table></el-collapse-item></el-collapse><el-pagination :current-page.sync="baselinePage" :total="baselineTotal" :page-size="10" layout="total,prev,pager,next" @current-change="loadBaselines"/></el-tab-pane><el-tab-pane label="采购成本" name="costs"><ProjectCosts v-if="form.id&&tab==='costs'" :key="form.id" :project-id="form.id"/><p v-else>请先保存项目，再关联采购明细。</p></el-tab-pane></el-tabs>
   <span slot="footer"><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存项目</el-button></span>
  </el-dialog>
 </div>
</template>
<script>
import ProjectGantt from '../components/ProjectGantt.vue';
import ProjectImport from '../components/ProjectImport.vue';
import ProjectCosts from '../components/ProjectCosts.vue';
import {api} from '../api/client';
const empty=()=>({code:'',name:'',manager_id:null,status:'draft',budget:0,currency:'CNY',description:'',tasks:[],version:1});
export default {
 components:{ProjectCosts,ProjectImport,ProjectGantt},
 data:()=>({items:[],staff:[],keyword:'',status:'',page:1,total:0,loading:false,saving:false,visible:false,tab:'tasks',alerts:[],baselines:[],baselinePage:1,baselineTotal:0,form:empty(),statuses:{draft:'草稿',active:'执行中',completed:'已完成',archived:'已归档'}}),
 computed:{datedTasks(){return this.form.tasks.filter(t=>t.start&&t.finish&&t.finish>=t.start);},bounds(){const t=this.datedTasks;return t.length?[Math.min(...t.map(t=>Date.parse(t.start))),Math.max(...t.map(t=>Date.parse(t.finish)))+86400000]:[0,1];},rangeLabel(){return this.datedTasks.length?new Date(this.bounds[0]).toISOString().slice(0,10)+' 至 '+new Date(this.bounds[1]-86400000).toISOString().slice(0,10):'';}},
 async created(){await this.load();if(this.$route.query.project){try{this.open((await api.get('/projects/'+this.$route.query.project)).data);}catch(e){this.error(e);}}try{let page=1;do{const r=(await api.get('/staff-users',{params:{page,page_size:100,status:'active'}})).data;this.staff.push(...r.items);if(page*100>=r.total)break;page++;}while(page<=100);}catch(e){this.error(e);}},
 methods:{async shiftSchedule(move){this.saving=true;try{const r=(await api.post('/projects/schedule-preview',{project:this.form,project_id:this.form.id||'',...move})).data;this.form.tasks=r.tasks;this.$message.success('已联动移动'+r.moved+'个任务，请保存项目');}catch(e){this.error(e);}finally{this.saving=false;}},async loadBaselines(){try{const r=(await api.get('/projects/'+this.form.id+'/baselines',{params:{page:this.baselinePage}})).data;this.baselines=r.items;this.baselineTotal=r.total;}catch(e){this.error(e);}},async createBaseline(){try{await this.$confirm('将服务端已保存的执行中计划确认为基线？弹窗未保存修改不会纳入。','确认基线');await api.post('/projects/'+this.form.id+'/baselines',null,{params:{version:this.form.version}});await this.loadBaselines();this.$message.success('基线已保存');}catch(e){if(e!=='cancel')this.error(e);}},async importXml(options){try{const f=new FormData();f.append('file',options.file);const r=(await api.post('/projects/import-xml',f)).data;this.open(r.draft);await this.$alert(r.warnings.join('\n'),'导入完成，请复核',{confirmButtonText:'完善草稿'});}catch(e){this.error(e);}},error(e){const d=e.response?.data?.detail;this.$message.error(typeof d==='string'?d:Array.isArray(d)?d[0].msg:'操作失败');},async load(){this.loading=true;try{const r=(await api.get('/projects',{params:{keyword:this.keyword,status:this.status,page:this.page,page_size:10}})).data;this.items=r.items;this.total=r.total;}catch(e){this.error(e);}finally{this.loading=false;}},staffName(id){return this.staff.find(s=>s.id===id)?.name||'未分配';},open(row){this.form=row?JSON.parse(JSON.stringify(row)):empty();this.alerts=[];this.baselines=[];this.baselinePage=1;this.baselineTotal=0;this.tab='tasks';this.visible=true;},addTask(){this.form.tasks.push({id:crypto.randomUUID(),name:'新任务',kind:'task',parent_id:null,owner_id:null,start:null,finish:null,progress:0,predecessors:[],source:''});},deleteTask(id){if(this.form.tasks.some(t=>t.parent_id===id||t.predecessors.includes(id))){this.$message.warning('请先解除其他任务对该任务的层级或前置关联');return;}this.form.tasks=this.form.tasks.filter(t=>t.id!==id);},bar(t){const [start,end]=this.bounds;return {left:((Date.parse(t.start)-start)/(end-start)*100)+'%',width:((Date.parse(t.finish)-Date.parse(t.start)+86400000)/(end-start)*100)+'%',background:t.progress===100?'#16a085':'#337ecc'};},async save(){this.saving=true;try{const payload={...this.form,manager_id:this.form.manager_id||null,tasks:this.form.tasks.map(t=>({...t,parent_id:t.parent_id||null,owner_id:t.owner_id||null}))};if(this.form.id)await api.put('/projects/'+this.form.id,payload);else await api.post('/projects',payload);this.visible=false;await this.load();this.$message.success('项目已保存');}catch(e){this.error(e);}finally{this.saving=false;}},async remove(row){try{await this.$confirm('删除该项目草稿？','确认');await api.delete('/projects/'+row.id,{params:{version:row.version}});await this.load();}catch(e){if(e!=='cancel')this.error(e);}},async checkAlerts(){try{this.alerts=(await api.get('/projects/'+this.form.id+'/alerts')).data.items;}catch(e){this.error(e);}}}
};
</script>
